package fr.zachiran.cercle;
import android.content.Context;import android.util.Base64;import org.json.JSONObject;
import java.io.*;import java.net.*;import java.security.*;import java.security.spec.X509EncodedKeySpec;
final class Api {
 static HttpURLConnection open(String url) throws Exception {DownloadPolicy.secure(url);URL u=new URL(url);HttpURLConnection c=(HttpURLConnection)u.openConnection();c.setConnectTimeout(15000);c.setReadTimeout(45000);c.setInstanceFollowRedirects(false);c.setRequestProperty("User-Agent","Cercle/0.3.3 Android");return c;}
 static JSONObject json(String url)throws Exception{HttpURLConnection c=open(url);c.setUseCaches(false);c.setRequestProperty("Cache-Control","no-cache");try{int code=c.getResponseCode();if(code!=200)throw new IOException(code==404?"Le catalogue n’est pas encore disponible. Réessayez après sa publication.":"Le catalogue est temporairement indisponible.");ByteArrayOutputStream bytes=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;try(InputStream in=c.getInputStream()){while((n=in.read(b))!=-1){bytes.write(b,0,n);if(bytes.size()>4*1024*1024)throw new IOException("Le catalogue est trop volumineux.");}}return new JSONObject(bytes.toString("UTF-8"));}finally{c.disconnect();}}
 static JSONObject verify(Context context,JSONObject envelope)throws Exception{byte[] payload=Base64.decode(envelope.getString("payload"),Base64.NO_WRAP),signature=Base64.decode(envelope.getString("signature"),Base64.NO_WRAP),key=Base64.decode(StoreConfig.key(context),Base64.NO_WRAP);if(!CatalogTrust.verify(payload,signature,key))throw new IOException("La signature du catalogue est invalide. Aucun fichier ne sera installé.");JSONObject catalog=new JSONObject(new String(payload,"UTF-8"));if(catalog.optInt("schema")!=2||!catalog.optString("repository").equals(StoreConfig.repository(context)))throw new IOException("Ce catalogue ne correspond pas à votre store.");if(catalog.getLong("revision")<1)throw new IOException("La version du catalogue est invalide.");return catalog;}
 static JSONObject catalog(Context c)throws Exception{String url=StoreConfig.catalog(c);JSONObject envelope=json(url+(url.contains("?")?"&":"?")+"check="+System.currentTimeMillis()),catalog=verify(c,envelope);return remember(c,envelope,catalog);}
 static synchronized JSONObject remember(Context c,JSONObject envelope,JSONObject catalog)throws Exception{long revision=catalog.getLong("revision"),last=Access.prefs(c).getLong("githubRevision",0);String digest=Packages.hex(MessageDigest.getInstance("SHA-256").digest(Base64.decode(envelope.getString("payload"),Base64.NO_WRAP)));if(revision<last||(revision==last&&!digest.equals(Access.prefs(c).getString("githubDigest",digest))))throw new IOException("Une ancienne version du catalogue a été reçue. Réessayez plus tard.");Access.prefs(c).edit().putString("githubCatalog",envelope.toString()).putLong("githubRevision",revision).putString("githubDigest",digest).apply();return catalog;}
 static JSONObject cached(Context c){try{return verify(c,new JSONObject(Access.prefs(c).getString("githubCatalog","")));}catch(Exception e){return null;}}
 static HttpURLConnection download(Context c,String url)throws Exception{DownloadPolicy.initial(url,StoreConfig.repository(c));return transfer(url);}
 static HttpURLConnection personalDownload(String url,String repo)throws Exception{GitHubSourcePolicy.download(url,repo);return transfer(url);}
 static HttpURLConnection transfer(String url)throws Exception{String current=url;for(int i=0;i<6;i++){HttpURLConnection connection=open(current);int code=connection.getResponseCode();if(code==200)return connection;if(code==301||code==302||code==303||code==307||code==308){String location=connection.getHeaderField("Location");connection.disconnect();if(location==null)throw new IOException("Le téléchargement est indisponible.");URL next=new URL(new URL(current),location);DownloadPolicy.redirect(next.toString());current=next.toString();}else{connection.disconnect();throw new IOException("L’APK n’est pas disponible pour le moment.");}}throw new IOException("Le téléchargement comporte trop de redirections.");}
}
